import json,glob,os,statistics,collections
rows=[]
for f in glob.glob('*.jsonl'):
    first=None; turns=0; tot_in=0; tot_out=0; cr=0; cw=0
    for line in open(f):
        try:d=json.loads(line)
        except:continue
        m=d.get('message') or {}
        u=m.get('usage') if isinstance(m,dict) else None
        if d.get('type')=='assistant' and u:
            s=u.get('input_tokens',0)+u.get('cache_creation_input_tokens',0)+u.get('cache_read_input_tokens',0)
            if first is None: first=(s,d.get('entrypoint'),m.get('model'),d.get('timestamp'))
            turns+=1; cr+=u.get('cache_read_input_tokens',0); cw+=u.get('cache_creation_input_tokens',0); tot_out+=u.get('output_tokens',0)
    if first: rows.append((first[3],first[0],first[1],first[2],turns,cr,cw,tot_out))
rows.sort()
for r in rows[-25:]: print(r)
g=collections.defaultdict(list)
for r in rows: g[(r[2],r[3])].append(r[1])
for k,v in g.items(): print(k,len(v),statistics.median(v))
EOF

